INSERT INTO content(id,content_type,content_format,card_type,title,summary,body,cover_url,author_id,source_type,source_name,is_official,view_count,like_count,comment_count,favorite_count,hot_score,publish_time,status,is_deleted,remark)
VALUES
  (16000000000000201,'POST','POST_FORMAT','CONTENT_CARD','圣西罗夜场的压迫感从哪里开始','从边路推进到中场回收，AC米兰的比赛节奏值得细看。','这场比赛的关键不只是最后一脚射门，而是球队如何在边路形成连续压迫。','/demo/p1-media/cover-stadium.png',11000000000000001,'USER','P1-M3 DEMO',0,124,18,2,7,340.00,'2026-09-16 09:20:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000202,'POST','POST_FORMAT','CONTENT_CARD','尤文图斯的中场三角如何撕开防线','围绕主场 2:0 的比赛，看看中场站位和前锋跑动。','尤文图斯在中路保持了清晰的三角站位，前场球员的交叉跑动让防线持续后退。','/demo/p1-media/cover-training.png',11000000000000002,'USER','P1-M3 DEMO',0,98,14,1,6,339.00,'2026-09-16 08:50:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000203,'ARTICLE','ARTICLE_FORMAT','CONTENT_CARD','门将站位：一次提前移动带来的收益','从门将的站位和出球选择，复盘本轮比赛中的防守细节。','门将不是最后一道静止的防线。提前半步的移动，常常决定了球队能否把进攻化解在危险区域之外。','/demo/p1-media/cover-tactics.png',11000000000000003,'USER','P1-M3 DEMO',0,156,22,2,11,338.00,'2026-09-16 08:20:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000204,'POST','POST_FORMAT','CONTENT_CARD','球员观察：无球跑动比数据更早发出信号','目标球员的跑动线路，解释了球队为什么能保持进攻宽度。','当球员不在镜头中心时，他的跑动仍然在改变防守选择。观察无球阶段，才能理解一次传球为什么会出现。','/demo/p1-media/cover-stadium.png',11000000000000004,'USER','P1-M3 DEMO',0,87,10,1,4,337.00,'2026-09-16 07:55:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000205,'ARTICLE','ARTICLE_FORMAT','CONTENT_CARD','旗舰比赛复盘：2:0 背后的三个转折点','尤文图斯与 AC 米兰的完整比赛复盘，串联事件、阵容和统计。','从第 11 分钟的进球到下半场换人，这场比赛的走势有三个清晰转折点。数据和现场节奏在这里彼此印证。','/demo/p1-media/cover-training.png',11000000000000005,'USER','P1-M3 DEMO',0,203,31,2,15,336.00,'2026-09-16 07:30:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000206,'POST','POST_FORMAT','CONTENT_CARD','看完比赛统计后，你最关注哪一项？','控球率、射门、传球成功率，哪一个指标最能解释比赛走势？','数据不是结论，但能帮助我们找到值得继续讨论的细节。欢迎结合比赛过程分享你的判断。','/demo/p1-media/cover-tactics.png',11000000000000006,'USER','P1-M3 DEMO',0,74,9,1,3,335.00,'2026-09-16 07:05:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000207,'POST','POST_FORMAT','CONTENT_CARD','从训练场到比赛日：年轻球员如何准备','训练中的重复动作，最终会在比赛的关键十分钟里显现。','准备工作并不总是显眼，但它会让球员在高压时刻更快做出正确选择。','/demo/p1-media/cover-stadium.png',11000000000000007,'USER','P1-M3 DEMO',0,66,8,1,2,334.00,'2026-09-16 06:40:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000208,'ARTICLE','ARTICLE_FORMAT','CONTENT_CARD','意甲赛季观察：两支球队的不同节奏','从球队赛季数据和阵容结构，观察两种比赛风格的差异。','同一轮比赛里，球队的节奏选择会影响控球、射门和防守站位。把单场表现放回赛季背景，结论会更完整。','/demo/p1-media/cover-training.png',11000000000000008,'USER','P1-M3 DEMO',0,111,17,0,8,333.00,'2026-09-16 06:15:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000209,'POST','POST_FORMAT','CONTENT_CARD','如果你来排阵，会保留哪一组首发？','结合阵型、事件和球员评分，聊聊你的比赛选择。','一套阵容的价值不只在纸面位置，也在于球员之间能否互相补位。欢迎从比赛数据出发讨论。','/demo/p1-media/cover-tactics.png',11000000000000009,'USER','P1-M3 DEMO',0,92,13,1,5,332.00,'2026-09-16 05:50:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT'),
  (16000000000000210,'ARTICLE','ARTICLE_FORMAT','CONTENT_CARD','赛后笔记：把现场感留在数据之外','一篇短小的赛后笔记，记录比赛中的节奏、情绪和细节。','当比分定格后，比赛仍然可以从不同角度被重新阅读。现场感和数据结合，才能留下更接近完整的记忆。','/demo/p1-media/cover-stadium.png',11000000000000010,'USER','P1-M3 DEMO',0,61,7,1,2,331.00,'2026-09-16 05:25:00','PUBLISHED',0,'P1_M3_DEMO_CONTENT')
