  (16200000000000201,16000000000000201,'TEXT','边路的宽度为中路回收创造了空间。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000202,16000000000000201,'TEXT','下一次复盘可以继续观察球队的压迫触发点。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000203,16000000000000202,'TEXT','中场三角让持球人始终拥有两个安全出球点。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000204,16000000000000202,'TEXT','前锋的无球移动把防守线拉出了缝隙。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000205,16000000000000203,'TEXT','门将站位的变化会直接影响后卫线的高度。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000206,16000000000000203,'TEXT','提前移动并不意味着冒险，而是更早读取进攻方向。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000207,16000000000000204,'TEXT','无球跑动是一种持续给队友制造选择的方式。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000208,16000000000000204,'TEXT','观察球员离开镜头后的线路，往往能补足比赛理解。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000209,16000000000000205,'TEXT','第一个进球改变了双方的风险偏好。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000210,16000000000000205,'TEXT','下半场换人让比赛进入了新的节奏。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000211,16000000000000206,'TEXT','控球率需要和射门质量、推进区域一起阅读。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000212,16000000000000206,'TEXT','数据的价值在于帮助我们提出更具体的问题。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000213,16000000000000207,'TEXT','训练中的重复会在比赛高压时刻变成下意识动作。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000214,16000000000000207,'TEXT','年轻球员的成长常常藏在这些细节里。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000215,16000000000000208,'TEXT','赛季数据能帮助我们区分偶然表现和稳定趋势。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000216,16000000000000208,'TEXT','球队风格最终会反映在阵容选择和比赛节奏上。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000217,16000000000000209,'TEXT','排阵时需要同时考虑球员状态、位置和相互补位。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000218,16000000000000209,'TEXT','同一场比赛可以支持多种合理的战术解释。',NULL,NULL,NULL,1,'ACTIVE',0),
  (16200000000000219,16000000000000210,'TEXT','比分之外，比赛留下的是一连串可以回看的瞬间。',NULL,NULL,NULL,0,'ACTIVE',0),(16200000000000220,16000000000000210,'TEXT','把现场感和数据放在一起，记忆会变得更立体。',NULL,NULL,NULL,1,'ACTIVE',0)
