VALUES
  (16400000000000201,'CONTENT',16000000000000201,0,16400000000000201,NULL,11000000000000002,'这场的边路推进确实很有层次。',8,1,12.00,1,NULL,'ACTIVE',0,'P1-M3-comment-201'),
  (16400000000000202,'CONTENT',16000000000000201,16400000000000201,16400000000000201,11000000000000002,11000000000000003,'我也注意到回收速度比上一场更快。',3,0,4.00,0,NULL,'ACTIVE',0,'P1-M3-comment-202'),
  (16400000000000203,'CONTENT',16000000000000202,0,16400000000000203,NULL,11000000000000004,'中场站位是这场比赛的关键。',6,0,8.00,0,NULL,'ACTIVE',0,'P1-M3-comment-203'),
  (16400000000000204,'CONTENT',16000000000000203,0,16400000000000204,NULL,11000000000000005,'门将的提前移动很值得复盘。',7,1,10.00,1,8.5,'ACTIVE',0,'P1-M3-comment-204'),
  (16400000000000205,'CONTENT',16000000000000203,16400000000000204,16400000000000204,11000000000000005,11000000000000006,'从回放看，站位变化确实很早。',2,0,3.00,0,NULL,'ACTIVE',0,'P1-M3-comment-205'),
  (16400000000000206,'CONTENT',16000000000000204,0,16400000000000206,NULL,11000000000000007,'无球跑动经常是最容易被忽略的部分。',5,0,7.00,0,NULL,'ACTIVE',0,'P1-M3-comment-206'),
  (16400000000000207,'CONTENT',16000000000000205,0,16400000000000207,NULL,11000000000000008,'两个转折点的判断很清楚。',9,1,14.00,1,NULL,'ACTIVE',0,'P1-M3-comment-207'),
  (16400000000000208,'CONTENT',16000000000000205,16400000000000207,16400000000000207,11000000000000008,11000000000000009,'换人之后的节奏变化尤其明显。',4,0,5.00,0,NULL,'ACTIVE',0,'P1-M3-comment-208'),
  (16400000000000209,'CONTENT',16000000000000206,0,16400000000000209,NULL,11000000000000010,'我会优先看射正和推进区域。',3,0,4.00,0,NULL,'ACTIVE',0,'P1-M3-comment-209'),
  (16400000000000210,'CONTENT',16000000000000207,0,16400000000000210,NULL,11000000000000001,'训练内容和比赛状态联系得很好。',4,0,6.00,0,NULL,'ACTIVE',0,'P1-M3-comment-210'),
  (16400000000000211,'CONTENT',16000000000000209,0,16400000000000211,NULL,11000000000000002,'排阵时我会保留一个速度型边锋。',5,0,7.00,0,NULL,'ACTIVE',0,'P1-M3-comment-211'),
  (16400000000000212,'CONTENT',16000000000000210,0,16400000000000212,NULL,11000000000000003,'数据和现场感结合起来更有意思。',2,0,3.00,0,NULL,'ACTIVE',0,'P1-M3-comment-212')
