USE south_stand;
SET NAMES utf8mb4;
SET collation_connection='utf8mb4_unicode_ci';

-- P1-M3 additive DEMO content set. Reuses M1 media and M2 football objects.
-- Reserved ranges are isolated from M1/M2 and all rows are idempotent.

DROP PROCEDURE IF EXISTS p1_m3_assert_safe;
DELIMITER $$
CREATE PROCEDURE p1_m3_assert_safe()
BEGIN
  IF EXISTS (SELECT 1 FROM content WHERE id>=16000000000000201 AND id<16000000000000211 AND (remark IS NULL OR remark<>'P1_M3_DEMO_CONTENT')) OR
     EXISTS (SELECT 1 FROM content_media WHERE id>=16100000000000201 AND id<16100000000000211 AND (remark IS NULL OR remark NOT LIKE 'P1-M3-media-%')) OR
     EXISTS (SELECT 1 FROM content_block WHERE id>=16200000000000201 AND id<16200000000000221 AND content_id NOT BETWEEN 16000000000000201 AND 16000000000000210) OR
     EXISTS (SELECT 1 FROM content_relation WHERE id>=16300000000000201 AND id<16300000000000216 AND (remark IS NULL OR remark NOT LIKE 'P1-M3-relation-%')) OR
     EXISTS (SELECT 1 FROM comment WHERE id>=16400000000000201 AND id<16400000000000213 AND (remark IS NULL OR remark NOT LIKE 'P1-M3-comment-%')) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='P1-M3 conflict: reserved range contains non-P1-M3 data';
  END IF;
END$$
DELIMITER ;
CALL p1_m3_assert_safe();
DROP PROCEDURE p1_m3_assert_safe;

START TRANSACTION;

ON DUPLICATE KEY UPDATE id=id;

ON DUPLICATE KEY UPDATE id=id;

ON DUPLICATE KEY UPDATE id=id;

ON DUPLICATE KEY UPDATE id=id;

ON DUPLICATE KEY UPDATE id=id;

UPDATE content c
SET c.comment_count=(SELECT COUNT(*) FROM comment x WHERE x.target_type='CONTENT' AND x.target_id=c.id AND x.status='ACTIVE' AND x.is_deleted=0)
WHERE c.id BETWEEN 16000000000000201 AND 16000000000000210 AND c.remark='P1_M3_DEMO_CONTENT';

COMMIT;

SELECT 'P1_M3_contents' metric,COUNT(*) value FROM content WHERE id BETWEEN 16000000000000201 AND 16000000000000210 AND remark='P1_M3_DEMO_CONTENT';
SELECT 'P1_M3_media' metric,COUNT(*) value FROM content_media WHERE id BETWEEN 16100000000000201 AND 16100000000000210 AND remark LIKE 'P1-M3-media-%';
SELECT 'P1_M3_comments' metric,COUNT(*) value FROM comment WHERE id BETWEEN 16400000000000201 AND 16400000000000212 AND remark LIKE 'P1-M3-comment-%';
